@startuml

class SensorController {
  + address : string
}

class Apartment {
  + address : string
  + inhabitants : int
}

class Inhabitant {
  + username : string
  + password : string
  + isAdmin : boolean
}

class Room {
  + description : string
}

class TemperatureSensor {
  + vendorId : string
  + description : string
  + unit : string
  + minValue : double
  + maxValue : double
  + threshold : double
  + room : Room
}

class PowerSensor {
  + vendorId : string
  + description : string
  + unit : string
  + counterReading : double
  + threshold : double
  + room : Room
}

class SensorValue {
  + timestamp : datetime
  + value : float
  + sensor : TemperatureSensor or PowerSensor
}

class EMonitor {}

class AlertMessage {
  + message : string
  + emailAddress : string
}

Apartment "1" -- "*" Inhabitant
Inhabitant "0..*" -- "1" Room
Room "1" -- "*" TemperatureSensor
Room "1" -- "*" PowerSensor
TemperatureSensor "0..*" -- "*" SensorValue
PowerSensor "0..*" -- "*" SensorValue
SensorController "1" *-- "* sensors" TemperatureSensor or PowerSensor
EMonitor "1" ..> SensorController : checks thresholds
SensorController "1" ..> EMonitor : sends alert messages

@enduml

